function openProductModal(id) {
  const p = (window.JIMON_PRODUCTS || []).find(x => x.id === id);
  if (!p) return;
  const modal = document.getElementById('productModal');
  if (!modal) return;
  document.getElementById('pmCat').textContent = p.catName || '';
  document.getElementById('pmTitle').textContent = p.title || '';
  document.getElementById('pmDesc').textContent = p.desc || '';
  document.getElementById('pmPrice').textContent = (p.price || 0).toLocaleString('ru-RU') + ' ₽';
  const imgBox = document.getElementById('pmImg');
  imgBox.innerHTML = p.img ? '<img src="'+p.img+'" alt="'+p.title+'">' : '<div style="font-size:4rem;text-align:center;padding:40px">🌿</div>';
  document.getElementById('pmOrderBtn').onclick = function() { closeProductModal(); openOrderModal(p.title); };
  modal.classList.add('on');
  modal.setAttribute('aria-hidden','false');
  document.body.style.overflow = 'hidden';
}
function closeProductModal() {
  const modal = document.getElementById('productModal');
  if (!modal) return;
  modal.classList.remove('on');
  modal.setAttribute('aria-hidden','true');
  document.body.style.overflow = '';
}
// ===== JIMON Catalog — Main JS =====

document.addEventListener('DOMContentLoaded', () => {
  // --- Navbar scroll effect ---
  const navbar = document.getElementById('navbar');
  const handleScroll = () => {
    if (window.scrollY > 60) {
      navbar.classList.add('scrolled');
    } else {
      navbar.classList.remove('scrolled');
    }
  };
  window.addEventListener('scroll', handleScroll, { passive: true });
  handleScroll();

  // --- Mobile menu ---
  const burger = document.getElementById('burger');
  const navLinks = document.querySelector('.nav-links');
  if (burger) {
    burger.addEventListener('click', () => {
      navLinks.classList.toggle('open');
      burger.classList.toggle('active');
    });
  }

  // --- Simple hero text parallax (river flows via CSS animation) ---
  const heroContent = document.querySelector('.hero-content');
  const scrollIndicator = document.querySelector('.scroll-indicator');

  const updateParallax = () => {
    const scrollY = window.scrollY;
    const heroHeight = window.innerHeight;

    if (heroContent) {
      const progress = Math.min(scrollY / heroHeight, 1);
      const translateY = scrollY * 0.4;
      const opacity = 1 - progress * 1.15;
      const scale = 1 - progress * 0.06;
      heroContent.style.transform = `translate3d(0, ${translateY}px, 0) scale(${scale})`;
      heroContent.style.opacity = Math.max(opacity, 0);
    }

    if (scrollIndicator) {
      scrollIndicator.style.opacity = Math.max(1 - scrollY / 180, 0);
    }
  };

  let ticking = false;
  window.addEventListener('scroll', () => {
    if (!ticking) {
      window.requestAnimationFrame(() => {
        updateParallax();
        ticking = false;
      });
      ticking = true;
    }
  }, { passive: true });
  
  updateParallax();

  // --- Counter animation ---
  const counters = document.querySelectorAll('.stat-num');
  let countersAnimated = false;

  const animateCounters = () => {
    if (countersAnimated) return;
    
    const hero = document.getElementById('hero');
    if (!hero) return;
    const rect = hero.getBoundingClientRect();
    
    if (rect.bottom > 100) {
      countersAnimated = true;
      counters.forEach(counter => {
        const target = parseInt(counter.dataset.count, 10);
        const duration = 2000;
        const start = performance.now();
        
        const update = (now) => {
          const progress = Math.min((now - start) / duration, 1);
          const ease = 1 - Math.pow(1 - progress, 3);
          const value = Math.floor(ease * target);
          counter.textContent = value.toLocaleString('ru-RU');
          
          if (progress < 1) {
            requestAnimationFrame(update);
          } else {
            counter.textContent = target.toLocaleString('ru-RU') + (target >= 100 ? '+' : '');
          }
        };
        requestAnimationFrame(update);
      });
    }
  };

  window.addEventListener('scroll', animateCounters, { passive: true });
  animateCounters();

  // --- Product filters ---
  const filterBtns = document.querySelectorAll('.filter-btn');
  const products = document.querySelectorAll('.product-card');

  filterBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      filterBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      const filter = btn.dataset.filter;

      products.forEach(card => {
        const category = card.dataset.category;
        if (filter === 'all' || category === filter) {
          card.classList.remove('hidden');
          card.style.animation = 'fadeUp 0.5s ease forwards';
        } else {
          card.classList.add('hidden');
        }
      });
    });
  });

  // --- Smooth reveal on scroll ---
  const revealElements = document.querySelectorAll('.about-card, .product-card, .adv-item');
  
  const revealObserver = new IntersectionObserver((entries) => {
    entries.forEach((entry, index) => {
      if (entry.isIntersecting) {
        setTimeout(() => {
          entry.target.style.opacity = '1';
          entry.target.style.transform = 'translateY(0)';
        }, index * 80);
        revealObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.15 });

  revealElements.forEach(el => {
    el.style.opacity = '0';
    el.style.transform = 'translateY(30px)';
    el.style.transition = 'opacity 0.6s ease, transform 0.6s ease';
    revealObserver.observe(el);
  });

  // --- Contact form ---
  const form = document.getElementById('contact-form');
  if (form) {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const btn = form.querySelector('button[type="submit"]');
      const originalText = btn.textContent;
      btn.textContent = 'Отправлено ✓';
      btn.style.background = '#2d9b66';
      setTimeout(() => {
        btn.textContent = originalText;
        btn.style.background = '';
        form.reset();
      }, 2500);
    });
  }

  // --- Smooth anchor scroll ---
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
      const targetId = this.getAttribute('href');
      if (targetId === '#') return;
      const target = document.querySelector(targetId);
      if (target) {
        e.preventDefault();
        const offset = 80;
        const top = target.getBoundingClientRect().top + window.scrollY - offset;
        window.scrollTo({ top, behavior: 'smooth' });
        
        // close mobile menu if open
        if (navLinks) navLinks.classList.remove('open');
        if (burger) burger.classList.remove('active');
      }
    });
  });
});


// ===== Order Modal =====
function openOrderModal(productName) {
  const modal = document.getElementById('orderModal');
  const label = document.getElementById('orderProductLabel');
  if (!modal) return;
  if (productName && label) {
    label.textContent = productName;
    label.classList.add('on');
  } else if (label) {
    label.textContent = '';
    label.classList.remove('on');
  }
  modal.classList.add('on');
  modal.setAttribute('aria-hidden', 'false');
  document.body.style.overflow = 'hidden';
}

function closeOrderModal() {
  const modal = document.getElementById('orderModal');
  if (!modal) return;
  modal.classList.remove('on');
  modal.setAttribute('aria-hidden', 'true');
  document.body.style.overflow = '';
}

document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') closeOrderModal();
});
